import type { CampaignPauseReason } from '~/client';

interface PauseReasonEntry {
  label: string;
}

export const campaignPauseReasonConfig: Record<CampaignPauseReason, PauseReasonEntry> = {
  target_reached: { label: 'Target Reached' },
  end_date: { label: 'End Date Reached' },
  project_completed: { label: 'Project Completed' },
  manual: { label: 'Manual' },
};

export function getCampaignPauseReason(reason: CampaignPauseReason): PauseReasonEntry {
  return campaignPauseReasonConfig[reason] ?? { label: snakeCaseToCapitalizedCase(reason) };
}
